def allPathsSourceTarget(graph: list[list[int]]) -> list[list[int]]:
    target = len(graph) - 1
    res = []
    def dfs(curr, path):
        if curr == target:
            res.append(list(path))
            return
        for nxt in graph[curr]:
            dfs(nxt, path + [nxt])
    dfs(0, [0])
    return sorted(res)

